import projectsData from "../data/Projects.json";
import caseStudies from "../data/CaseStudies.json";
import technologyUsage from "../data/TechnologyUsage.json";
import { filterProjects, getTechnologyConnection, matchesTechnology, projectMatchesTechnology, technologyLabel } from "../utils/portfolioEvidence";
import experienceData from "../data/Experience.json";
import techStackData from "../data/TechStack.json";
import involvementsData from "../data/Involvements.json";
import achievementsData from "../data/Achievements.json";

const uniqueTechnologies = tools => [...new Set(tools.map(technologyLabel))];
const defaultRoles = {
    Git: 'Source control used for this project.',
    Linux: 'Linux used in the project environment.',
    Jenkins: 'Jenkins used for this project’s delivery pipeline.',
    AWS: 'AWS used for this project’s cloud environment.',
};

/**
 * PortfolioService
 * Centralizes data access for the portfolio.
 * Follows SOLID principles by decoupling data sources from UI components.
 */
const PortfolioService = {
    getProjects: () => {
        return [
            ...caseStudies,
            ...projectsData.map((project, index) => ({
                ...project,
                id: project.id || `archive-${index}`,
                source: project.source || 'Portfolio archive',
                company: project.company || 'Earlier portfolio',
                companyId: project.companyId || 'archive',
            })),
        ].map(project => {
            const companyUsage = technologyUsage.companies[project.companyId] || {};
            const projectTools = [...technologyUsage.allProjects, ...(companyUsage.allProjects || [])];
            const techStack = uniqueTechnologies([...project.techStack, ...projectTools]);
            const sharedTechStack = uniqueTechnologies(companyUsage.sharedStack || [])
                .filter(tool => !techStack.some(implemented => matchesTechnology(implemented, tool)));
            const confirmed = [...techStack, ...sharedTechStack];
            return {
                ...project,
                techStack,
                sharedTechStack,
                technologyUsage: {
                    ...Object.fromEntries(projectTools.map(tool => [tool, defaultRoles[tool]])),
                    ...project.technologyUsage,
                },
                relatedSkills: (project.relatedSkills || [])
                    .map(skill => ({ ...skill, name: technologyLabel(skill.name) }))
                    .filter(skill => !confirmed.some(tool => matchesTechnology(tool, skill.name))),
            };
        });
    },

    getExperience: () => {
        return experienceData.map(job => {
            if (!job.description) return job;
            const companyUsage = technologyUsage.companies[job.id] || {};
            return {
                ...job,
                techStack: uniqueTechnologies([...(job.techStack || []), ...technologyUsage.allProjects, ...(companyUsage.allProjects || []), ...(companyUsage.sharedStack || [])]),
                sharedTechStack: uniqueTechnologies(companyUsage.sharedStack || []),
            };
        });
    },

    getTechStack: () => {
        const projects = PortfolioService.getProjects();
        return techStackData.map(category => ({
            ...category,
            technologies: category.technologies.map(skill => {
                const matchedProjects = projects.filter(project => projectMatchesTechnology(project, skill.name));
                const projectIds = matchedProjects.map(project => project.id);
                const relatedProjectCount = matchedProjects.filter(project => getTechnologyConnection(project, skill.name).kind === 'related').length;
                const companyProjectCount = matchedProjects.filter(project => getTechnologyConnection(project, skill.name).kind === 'company').length;
                return { ...skill, projectIds, projectCount: projectIds.length, relatedProjectCount, companyProjectCount };
            }),
        }));
    },

    getInvolvements: () => {
        return involvementsData;
    },

    getAchievements: () => {
        return achievementsData;
    },

    /**
     * Example of an advanced feature: Filter projects by tech stack.
     * Demonstrates the power of a centralized service.
     */
    getProjectsByTech: (tech) => {
        return filterProjects(PortfolioService.getProjects(), { technology: tech });
    },
};

export default PortfolioService;
