// Only alternate names for the same technology belong here. A framework does
// not imply every library commonly used with it (or a particular employer).
const technologyAliases = {
  'Java': [],
  'JavaScript': [],
  'TypeScript': [],
  'React': [],
  'Angular': [],
  'SQL': [],
  'Spring Boot': ['SpringBoot'],
  'Spring Cloud': ['SpringCloud'],
  'Spring Security': ['SpringSecurity'],
  'Apache Kafka': ['Kafka', 'Kafka-driven'],
  'Elasticsearch': ['ElasticSearch', 'Elastic Search'],
  'LLM Integration': ['LLM', 'LLMs'],
  'Vector Embeddings': ['Embeddings'],
  'MongoDB': ['Mongo', 'Mongo DB'],
  'MySQL': ['My SQL'],
  'PostgreSQL': ['Postgres', 'Postgre SQL'],
  'Jenkins': ['CI/CD (Jenkins)', 'Jenkins CI/CD'],
  'RESTful APIs': ['REST', 'RESTful', 'REST API', 'REST APIs', 'RESTful API'],
  'CSS3/SCSS': ['CSS', 'CSS3', 'SCSS'],
  'HTML5': ['HTML'],
  'AWS': ['Amazon Web Services'],
};

const normalize = value => String(value ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const aliasKeys = new Map();
const labels = new Map();
Object.entries(technologyAliases).forEach(([name, aliases]) => {
  const key = normalize(name);
  labels.set(key, name);
  [name, ...aliases].forEach(alias => aliasKeys.set(normalize(alias), key));
});

export function technologyKey(value = '') {
  const fullKey = normalize(value);
  const baseKey = normalize(String(value ?? '').replace(/\s*\([^)]*\)/g, ''));
  return aliasKeys.get(fullKey) || aliasKeys.get(baseKey) || baseKey;
}

export function technologyLabel(value = '') {
  return labels.get(technologyKey(value)) || String(value ?? '').trim();
}

export function matchesTechnology(value, selected) {
  const key = technologyKey(selected);
  return Boolean(key) && technologyKey(value) === key;
}

export function projectUsesTechnology(project, technology) {
  return Boolean(project.techStack?.some(tool => matchesTechnology(tool, technology)));
}

export function getTechnologyConnection(project, technology) {
  if (projectUsesTechnology(project, technology)) {
    return { kind: 'implemented', role: project.technologyUsage?.[technologyLabel(technology)] || '' };
  }
  if (project.sharedTechStack?.some(tool => matchesTechnology(tool, technology))) {
    return { kind: 'company', role: `Part of the shared technology stack used at ${project.company}.` };
  }
  const related = project.relatedSkills?.find(skill => matchesTechnology(skill.name, technology));
  return related ? { kind: 'related', role: related.role } : null;
}

export function projectMatchesTechnology(project, technology) {
  return Boolean(getTechnologyConnection(project, technology));
}

export function getProjectTechnologies(project) {
  return [...new Set([...(project.techStack || []), ...(project.sharedTechStack || []), ...(project.relatedSkills || []).map(skill => skill.name)].map(technologyLabel))];
}

export function getSkillEvidence(skill, experience = [], projects = []) {
  if (!skill?.name) return { companies: [], projects: [] };
  const work = projects.filter(project => projectMatchesTechnology(project, skill.name))
    .map(project => ({ ...project, technologyConnection: getTechnologyConnection(project, skill.name) }));
  const companies = experience.filter(job => job.description).map(job => {
    // Employer links come from an explicitly mapped project and contribution.
    // Searching company prose produced links that disagreed with project filters.
    const linkedIndexes = new Set(work
      .filter(project => project.technologyConnection.kind === 'implemented' && project.companyId === job.id && Number.isInteger(project.sourceIndex))
      .map(project => project.sourceIndex));
    const contributions = job.description
      .map((description, index) => ({ description, index, title: job.contributionTitles?.[index] }))
      .filter(item => linkedIndexes.has(item.index));
    const sharedUsage = Boolean(job.sharedTechStack?.some(tool => matchesTechnology(tool, skill.name)));
    return { ...job, contributions, sharedUsage };
  }).filter(job => job.contributions.length > 0 || job.sharedUsage);
  return { companies, projects: work };
}

export function filterProjects(projects, { query = '', technology = '', company = '' } = {}) {
  const search = query.trim().toLowerCase();
  return projects.filter(project => (
    (!technology || projectMatchesTechnology(project, technology)) &&
    (!company || project.companyId === company) &&
    (!search || [project.title, project.content, project.company, ...getProjectTechnologies(project)].join(' ').toLowerCase().includes(search))
  ));
}
